59	// Check if an instruction has the julia.reset_safe metadata
60	static bool hasResetSafeMetadata(Instruction *I) {
61	    return I->getMetadata("julia.reset_safe") != nullptr;
62	}
63	
64	// Mark an instruction created by this pass as reset-safe, so the unsafe-point
65	// walk does not treat the pass's own reset_ctx bookkeeping as program state
66	// that a reset could tear.
67	static void setResetSafeMetadata(Instruction *I) {
68	    I->setMetadata("julia.reset_safe", MDNode::get(I->getContext(), {}));
69	}
70	
71	// Machinery that codegen/the runtime inserts implicitly - calls into the
72	// runtime library (boxing, error throws, generic dispatch, exception-stack
73	// manipulation, ...) - is not part of the IPO contract that lets inference
74	// tag a statement reset_safe, and the runtime-internal frames implementing
75	// it (malloc, exception setup, the JIT) must never be abandoned by a
76	// delivered reset. Such calls eagerly drop the published reset context in
77	// every function, even where the covering source statement was proven
78	// reset-safe. (Interrupt-safe insertions - the GC safepoint, pure address
79	// computations - are exempted by the callers of this predicate, and
80	// allocations/write barriers are handled by the *_reset_safe runtime entry
81	// points selected in FinalLowerGC instead.)
82	static bool isImplicitRuntimeCall(CallInst *CI) {
83	    Function *Callee = CI->getCalledFunction();
84	    if (!Callee || Callee->isIntrinsic())
85	        return false;
86	    StringRef Name = Callee->getName();
87	    if (Name.starts_with("julia.call"))
88	        return true;
89	    // The setjmp calls emitted for exception handlers (and by this pass) are
90	    // pure register/buffer saves.
91	    if (Name == jl_setjmp_name)
92	        return false;
93	    // Runtime library helpers. This deliberately over-approximates (it also
94	    // matches explicit ccalls into libjulia): dropping the region around a
95	    // call that did not need it only delays delivery, never breaks it.
96	    return Name.starts_with("ijl_") || Name.starts_with("jl_");
97	}
