101	struct CancellationLowering {
102	    Function *cancel_point_func;
103	    Value *pgcstack;
104	    Value *reset_ctx_ptr;  // Computed once in entry block, dominates all uses
105	    Value *ptls_field_ptr; // Pointer to task->ptls, computed alongside reset_ctx_ptr
106	    Value *eh_field_ptr;   // Pointer to task->eh, computed alongside reset_ctx_ptr
107	
108	    CancellationLowering(Module &M) : cancel_point_func(nullptr), pgcstack(nullptr), reset_ctx_ptr(nullptr), ptls_field_ptr(nullptr), eh_field_ptr(nullptr) {
109	        cancel_point_func = M.getFunction("julia.cancellation_point");
110	    }
111	
112	    bool runOnFunction(Function &F);
113	
114	private:
115	    // Compute reset_ctx_ptr once in entry block
116	    // If insertAfter is provided, insert after that instruction
117	    // Otherwise insert at the beginning of the entry block (after allocas)
118	    void computeResetCtxPtr(Function &F, Instruction *insertAfter);
119	};
120	
121	void CancellationLowering::computeResetCtxPtr(Function &F, Instruction *insertAfter) {
122	    if (!pgcstack)
123	        return;
124	
125	    LLVMContext &LLVMCtx = F.getContext();
126	    Type *I8Ty = Type::getInt8Ty(LLVMCtx);
127	    Type *I64Ty = Type::getInt64Ty(LLVMCtx);
128	
129	    IRBuilder<> Builder(LLVMCtx);
130	    if (insertAfter) {
131	        // Insert right after pgcstack call
132	        Builder.SetInsertPoint(insertAfter->getNextNode());
133	    } else {
134	        // pgcstack is an argument, insert at the start of entry block
135	        // but after any allocas
136	        BasicBlock &entry = F.getEntryBlock();
137	        BasicBlock::iterator insertPt = entry.begin();
138	        while (insertPt != entry.end() && isa<AllocaInst>(&*insertPt)) {
139	            ++insertPt;
140	        }
141	        Builder.SetInsertPoint(&entry, insertPt);
142	    }
143	
144	    // Get the offset of gcstack in jl_task_t
145	    size_t gcstack_offset = offsetof(jl_task_t, gcstack);
146	
147	    Value *task_ptr = Builder.CreateGEP(I8Ty, pgcstack,
148	                                        ConstantInt::get(I64Ty, -(int64_t)gcstack_offset),
149	                                        "current_task");
150	
151	    // Get pointer to reset_ctx field in current task
152	    size_t reset_ctx_offset = offsetof(jl_task_t, reset_ctx);
153	
154	    reset_ctx_ptr = Builder.CreateGEP(I8Ty, task_ptr,
155	                                       ConstantInt::get(I64Ty, reset_ctx_offset),
156	                                       "reset_ctx_ptr");
157	
158	    ptls_field_ptr = Builder.CreateGEP(I8Ty, task_ptr,
159	                                       ConstantInt::get(I64Ty, offsetof(jl_task_t, ptls)),
160	                                       "ptls_field_ptr");
161	
162	    eh_field_ptr = Builder.CreateGEP(I8Ty, task_ptr,
163	                                     ConstantInt::get(I64Ty, offsetof(jl_task_t, eh)),
164	                                     "eh_field_ptr");
165	}
