167	bool CancellationLowering::runOnFunction(Function &F) {
168	    bool Changed = false;
169	
170	    // Find pgcstack - either as a call to julia.get_pgcstack or as an argument with "gcstack" attribute
171	    pgcstack = nullptr;
172	    reset_ctx_ptr = nullptr;
173	    eh_field_ptr = nullptr;
174	    Instruction *pgcstack_inst = nullptr;  // Only set if pgcstack is from a call, not an argument
175	    Function *pgcstack_getter = F.getParent()->getFunction("julia.get_pgcstack");
176	    Function *adoptthread_func = F.getParent()->getFunction("julia.get_pgcstack_or_new");
177	    if (pgcstack_getter || adoptthread_func) {
178	        for (auto &I : F.getEntryBlock()) {
179	            if (CallInst *callInst = dyn_cast<CallInst>(&I)) {
180	                Value *callee = callInst->getCalledOperand();
181	                if ((pgcstack_getter && callee == pgcstack_getter) ||
182	                    (adoptthread_func && callee == adoptthread_func)) {
183	                    pgcstack = callInst;
184	                    pgcstack_inst = callInst;
185	                    break;
186	                }
187	            }
188	        }
189	    }
190	    // If not found via call, check for argument with "gcstack" attribute
191	    if (!pgcstack) {
192	        for (auto &arg : F.args()) {
193	            AttributeSet attrs = F.getAttributes().getParamAttrs(arg.getArgNo());
194	            if (attrs.hasAttribute("gcstack")) {
195	                pgcstack = &arg;
196	                break;
197	            }
198	        }
199	    }
200	
201	    // First, find all cancellation_point intrinsics (walking the users of
202	    // the declaration rather than every instruction of the function)
203	    SmallVector<CallInst*, 4> CancellationPoints;
204	
205	    if (cancel_point_func) {
206	        for (User *U : cancel_point_func->users()) {
207	            if (auto *CI = dyn_cast<CallInst>(U)) {
208	                if (CI->getFunction() == &F &&
209	                    CI->getCalledOperand() == cancel_point_func)
210	                    CancellationPoints.push_back(CI);
211	            }
212	        }
213	    }
214	
215	    // A function without cancellation points of its own still participates
216	    // when codegen marked it julia.ipo_reset_safe: it may run inside a
217	    // caller's reset region (kept open across a reset_safe call), so its
218	    // implicitly-inserted runtime machinery and untagged calls must eagerly
219	    // drop the region. Any other function can never run inside an open
220	    // region and needs no instrumentation. (Without access to the task
221	    // pointer nothing can be done either - but then the function cannot
222	    // contain the operations that need dropping.)
223	    bool instrumented = !CancellationPoints.empty();
224	    if (!instrumented && (!pgcstack || !F.hasFnAttribute("julia.ipo_reset_safe")))
225	        return false;
226	
227	    // Sanitizer instrumentation runs AFTER this pass (see addSanitizerPasses
228	    // in pipeline.cpp) and rewrites stores into sanitizer runtime calls -
229	    // including this pass's own reset_ctx bookkeeping - inside code already
230	    // classified as reset-safe. A delivered reset could then abandon a
231	    // sanitizer runtime frame, whose bookkeeping cannot be repaired since
232	    // Julia bypasses the sanitizers' longjmp interceptors (see jl_longjmp in
233	    // julia.h). Under TSan, do not establish reset regions at all: lower
234	    // cancellation points to a plain safepoint + status check (delivery
235	    // degrades to level-triggered polling).
236	    bool no_publish = F.hasFnAttribute(Attribute::SanitizeThread);
237	    if (no_publish && !instrumented)
238	        return false;
239	
240	
241	    // Compute reset_ctx_ptr once in entry block (dominates all uses)
242	    // pgcstack_inst is set when pgcstack comes from a call; null when it's an argument
243	    if (instrumented)
244	        computeResetCtxPtr(F, pgcstack_inst);
245	
246	    // Lower each cancellation point, remembering each region's publication
247	    // for the reachability computation below. All points of a function share
248	    // one region buffer: regions never nest within a frame - each point's
249	    // publication supersedes the previous one, and "the region" is always
250	    // "since the most recently crossed point" - so the buffer identifies the
251	    // frame, not the point.
252	    SmallVector<Instruction*, 4> PointPublishes;
253	    AllocaInst *UContextBuf = nullptr;
254	    for (CallInst *CI : CancellationPoints) {
255	        ++CancellationPointsLowered;
256	        Changed = true;
257	
258	        IRBuilder<> Builder(CI);
259	        LLVMContext &LLVMCtx = F.getContext();
260	        Type *I8Ty = Type::getInt8Ty(LLVMCtx);
261	        Type *I32Ty = Type::getInt32Ty(LLVMCtx);
262	        Type *I64Ty = Type::getInt64Ty(LLVMCtx);
263	        Type *PtrTy = PointerType::getUnqual(LLVMCtx);
264	
265	        // Codegen materializes the current task before emitting the marker,
266	        // so a function containing a cancellation point always has a
267	        // pgcstack; silently folding the point away would swallow
268	        // cancellation.
269	        assert(reset_ctx_ptr && "julia.cancellation_point in a function without pgcstack");
270	
271	        if (no_publish) {
272	            // A cancellation point remains a GC safepoint and a poll even
273	            // without a reset region.
274	            Value *ptls = Builder.CreateAlignedLoad(PtrTy, ptls_field_ptr, Align(sizeof(void*)), "ptls");
275	            Type *T_size = F.getParent()->getDataLayout().getIntPtrType(LLVMCtx);
276	            emit_gc_safepoint(Builder, T_size, ptls, nullptr, false);
277	            CI->replaceAllUsesWith(ConstantInt::get(I32Ty, 0));
278	            CI->eraseFromParent();
279	            continue;
280	        }
281	
282	        // Allocate one jl_reset_ctx_t on the stack, shared by every point
283	        // of this function (see above).
284	        if (!UContextBuf) {
285	            const size_t UContextSize = sizeof(jl_reset_ctx_t);
286	            const size_t UContextAlign = alignof(jl_reset_ctx_t);
287	            // Create the alloca at the start of the function
288	            IRBuilder<> AllocaBuilder(&F.getEntryBlock().front());
289	            Type *UContextTy = ArrayType::get(I8Ty, UContextSize);
290	            UContextBuf = AllocaBuilder.CreateAlloca(UContextTy, nullptr, "cancel_ucontext");
291	            UContextBuf->setAlignment(Align(UContextAlign));
292	        }
293	
294	        // If this frame's region is still published, the whole establishment
295	        // (and its safepoint) is skipped: the buffer already holds a valid
296	        // setjmp of an earlier point of this frame, and landing there is
297	        // equivalent to landing here. For a cancellation delivery the
298	        // landing throws either way; for a preempt delivery the landing
299	        // resumes at the earlier point and re-executes forward - sound
300	        // because everything a surviving region spans is re-executable by
301	        // construction (that is what keeps a region open), the same
302	        // re-execution any preempt reset performs, just from further back.
303	        // The equivalence also covers the governing token: codegen emits
304	        // the point's binding bookkeeping before the marker, and its rebind
305	        // stores are untagged - unsafe points whose pass-inserted clear
306	        // tears the region - so a region that is still live here was
307	        // established under the very token this point just verified as
308	        // bound (exception handlers restore the pair together, and finalizers
309	        // only run with the region unpublished).
310	        // The load is
311	        // exact ground truth - the region survived if and only if no unsafe
312	        // point (whose pass-inserted clear nulls reset_ctx) ran since the
313	        // establishment - so this is robust against any CFG shape the
314	        // optimizer produced, and re-establishes precisely when needed
315	        // (function entry, after a region-tearing operation, after the
316	        // slow path's handle_cancellation! call). No consumption race: the
317	        // published context is only ever consumed by same-thread signal
318	        // delivery (control never returns here) or with this thread frozen.
319	        // Skipping the safepoint means a pure-compute polling loop only
320	        // polls at its establishing crossing - the historical behavior of
321	        // uninstrumented pure loops (which never poll); any loop doing real
322	        // work still polls through its allocations, or re-establishes (with
323	        // the safepoint) after the calls that tore its region - and unlike
324	        // an uninstrumented spin, this one stays cancellable, which is also
325	        // the escape hatch for a stop-the-world it delays.
326	        BasicBlock *ContBB = CI->getParent()->splitBasicBlock(CI, "cancel_pt_cont");
327	        BasicBlock *CheckBB = ContBB->getSinglePredecessor();
328	        BasicBlock *EstablishBB = BasicBlock::Create(LLVMCtx, "cancel_establish", &F, ContBB);
329	        CheckBB->getTerminator()->eraseFromParent();
330	        Builder.SetInsertPoint(CheckBB);
331	        LoadInst *prev = Builder.CreateAlignedLoad(PtrTy, reset_ctx_ptr, Align(sizeof(void*)), /*isVolatile*/true, "reset_ctx_prev");
332	        prev->setOrdering(AtomicOrdering::Monotonic);
333	        setResetSafeMetadata(prev);
334	        Value *already = Builder.CreateICmpEQ(prev, UContextBuf, "region_live");
335	        Builder.CreateCondBr(already, ContBB, EstablishBB);
336	        Builder.SetInsertPoint(EstablishBB);
337	
338	        // N.B.: The buffer may only be published in `reset_ctx` while its
339	        // contents are valid; a cancellation signal arriving in between would
340	        // otherwise longjmp into garbage. Since `setjmp` below (re-)writes the
341	        // buffer (cancellation points in loops re-execute it), unpublish the
342	        // buffer first, then write it, then publish it. All reset_ctx stores
343	        // and the buffer writes are volatile: delivery observes them
344	        // asynchronously (a signal on the same thread, or a suspender), so
345	        // they must be emitted exactly where placed. The single-thread
346	        // (signal) fence keeps the buffer writes from being reordered above
347	        // the unpublish by any later pass.
348	        Value *null_ptr0 = ConstantPointerNull::get(cast<PointerType>(PtrTy));
349	        StoreInst *unpub = Builder.CreateAlignedStore(null_ptr0, reset_ctx_ptr, Align(sizeof(void*)), /*isVolatile*/true);
350	        unpub->setOrdering(AtomicOrdering::Release);
351	        setResetSafeMetadata(unpub);
352	        Builder.CreateFence(AtomicOrdering::SequentiallyConsistent, SyncScope::SingleThread);
353	
354	        // An establishing cancellation point is also a GC safepoint: it sits
355	        // on every entry into region-covered code (and on the re-arm path
356	        // after anything tore the region), so cancellation-instrumented code
357	        // cannot starve a stop-the-world request any worse than the same
358	        // code without instrumentation. This must be emitted while reset_ctx
359	        // is unpublished, so that a concurrently delivered cancellation
360	        // signal cannot longjmp us out of the safepoint wait.
361	        Value *ptls = Builder.CreateAlignedLoad(PtrTy, ptls_field_ptr, Align(sizeof(void*)), "ptls");
362	        Type *T_size = F.getParent()->getDataLayout().getIntPtrType(LLVMCtx);
363	        emit_gc_safepoint(Builder, T_size, ptls, nullptr, false);
364	
365	        // Stamp the buffer's discriminator: a nonzero `sp` (the buffer's own
366	        // frame address) marks it as a reset-flavor context (see
367	        // jl_reset_ctx_t). Atomic monotonic since the delivery machinery
368	        // reads it from another thread.
369	        Value *sp_val = Builder.CreatePtrToInt(UContextBuf, T_size);
370	        StoreInst *sp_store = Builder.CreateAlignedStore(sp_val, UContextBuf, Align(alignof(jl_reset_ctx_t)), /*isVolatile*/true);
371	        sp_store->setOrdering(AtomicOrdering::Monotonic);
372	        setResetSafeMetadata(sp_store);
373	
374	        // Record the task's GC-frame chain head and innermost exception
375	        // handler at establishment: a delivered reset may interrupt a
376	        // reset-safe callee that pushed frames of its own onto either chain,
377	        // all of which die with the abandoned stack region, so the delivery
378	        // restores both saved values before the longjmp. (pgcstack points
379	        // directly at the task's gcstack field.)
380	        Value *gcstack_val = Builder.CreateAlignedLoad(PtrTy, pgcstack, Align(sizeof(void*)), "saved_gcstack");
381	        Value *GCStackSlot = Builder.CreateGEP(I8Ty, UContextBuf,
382	                                               ConstantInt::get(I64Ty, offsetof(jl_reset_ctx_t, gcstack)),
383	                                               "cancel_gcstack_slot");
384	        StoreInst *gcstack_store = Builder.CreateAlignedStore(gcstack_val, GCStackSlot, Align(sizeof(void*)), /*isVolatile*/true);
385	        setResetSafeMetadata(gcstack_store);
386	        Value *eh_val = Builder.CreateAlignedLoad(PtrTy, eh_field_ptr, Align(sizeof(void*)), "saved_eh");
387	        Value *EhSlot = Builder.CreateGEP(I8Ty, UContextBuf,
388	                                          ConstantInt::get(I64Ty, offsetof(jl_reset_ctx_t, eh)),
389	                                          "cancel_eh_slot");
390	        StoreInst *eh_store = Builder.CreateAlignedStore(eh_val, EhSlot, Align(sizeof(void*)), /*isVolatile*/true);
391	        setResetSafeMetadata(eh_store);
392	
393	        // Call setjmp on the mctx field.
394	        // Use the platform-specific setjmp function name defined in julia.h
395	        Value *MCtxPtr = Builder.CreateGEP(I8Ty, UContextBuf,
396	                                           ConstantInt::get(I64Ty, offsetof(jl_reset_ctx_t, mctx)),
397	                                           "cancel_mctx");
398	        // Match the target-specific signature codegen uses for jl_setjmp
399	        // (see setjmp_func in codegen.cpp): Windows' _setjmp variant takes
400	        // only the buffer argument.
401	        const Triple TT(F.getParent()->getTargetTriple());
402	        FunctionType *SetjmpTy;
403	        SmallVector<Value*, 2> SetjmpArgs;
404	        if (TT.isOSWindows()) {
405	            SetjmpTy = FunctionType::get(I32Ty, {PtrTy}, false);
406	            SetjmpArgs.push_back(MCtxPtr);
407	        }
408	        else {
409	            SetjmpTy = FunctionType::get(I32Ty, {PtrTy, I32Ty}, false);
410	            SetjmpArgs.push_back(MCtxPtr);
411	            SetjmpArgs.push_back(ConstantInt::get(I32Ty, 0));
412	        }
413	        FunctionCallee SetjmpFn = F.getParent()->getOrInsertFunction(jl_setjmp_name, SetjmpTy);
414	
415	        CallInst *SetjmpCall = Builder.CreateCall(SetjmpFn, SetjmpArgs);
416	        SetjmpCall->addFnAttr(Attribute::ReturnsTwice);
417	
418	        // Publish the now-valid buffer address to reset_ctx (release, so that
419	        // the buffer contents are visible before the pointer; the setjmp call
420	        // itself keeps the store from moving up).
421	        StoreInst *store = Builder.CreateAlignedStore(UContextBuf, reset_ctx_ptr, Align(sizeof(void*)), /*isVolatile*/true);
422	        store->setOrdering(AtomicOrdering::Release);
423	        setResetSafeMetadata(store);
424	        PointPublishes.push_back(store);
425	        Builder.CreateBr(ContBB);
426	
427	        // Replace uses and remove the intrinsic. (The marker's value is
428	        // unused by codegen; keep a PHI for IR sanity should that change.)
429	        if (!CI->use_empty()) {
430	            IRBuilder<> PhiBuilder(&ContBB->front());
431	            PHINode *phi = PhiBuilder.CreatePHI(I32Ty, 2);
432	            phi->addIncoming(ConstantInt::get(I32Ty, 0), CheckBB);
433	            phi->addIncoming(SetjmpCall, EstablishBB);
434	            CI->replaceAllUsesWith(phi);
435	        }
436	        CI->eraseFromParent();
437	    }
438	
439	    // When regions are not published (sanitizer builds), there is nothing
440	    // to maintain either.
441	    if (no_publish)
442	        return Changed;
443	
444	    // A region can only be open at an instruction reachable from one of the
445	    // publications (or anywhere, when the function may inherit an open
446	    // region from its caller across a reset_safe call - it carries the
447	    // julia.ipo_reset_safe attribute). Instructions outside that set need
448	    // neither clears nor teardown nor site annotations.
449	    bool inherits_region = F.hasFnAttribute("julia.ipo_reset_safe");
450	    SmallPtrSet<BasicBlock*, 16> MayBeOpenAtEntry;
451	    if (!inherits_region) {
452	        SmallVector<BasicBlock*, 8> Worklist;
453	        for (Instruction *Pub : PointPublishes)
454	            for (BasicBlock *Succ : successors(Pub->getParent()))
455	                Worklist.push_back(Succ);
456	        while (!Worklist.empty()) {
457	            BasicBlock *B = Worklist.pop_back_val();
